import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

/**
 * A book store backed by a single JSON file.
 *
 * The whole collection is small enough to keep in memory, so reads are served
 * from the cache and every mutation rewrites the file. Writes are serialised
 * through `queue` and go via a temp file + rename so an interrupted write can
 * never leave a half-written books.json behind.
 */
export function createStore(filePath) {
  let books = null;
  let queue = Promise.resolve();

  async function load() {
    if (books) return books;

    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (err) {
      if (err.code === 'ENOENT') {
        books = [];
        return books;
      }
      throw err;
    }

    if (raw.trim() === '') {
      books = [];
      return books;
    }

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      // Refuse to start rather than quietly overwriting the file with an empty
      // list — the reading history is the only copy of the user's data.
      throw new Error(
        `${filePath} is not valid JSON, so it was not loaded. Fix or move the file, then restart. (${err.message})`
      );
    }
    if (!Array.isArray(parsed)) {
      throw new Error(`${filePath} should contain a JSON array of books.`);
    }

    books = parsed;
    return books;
  }

  // Serialise writes so two concurrent form posts can't interleave and lose one.
  function write(mutate) {
    queue = queue.then(async () => {
      await load();
      const result = mutate();
      await mkdir(path.dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${randomUUID()}.tmp`;
      await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
      await rename(tmp, filePath);
      return result;
    });
    return queue;
  }

  return {
    async all() {
      return [...(await load())];
    },

    /** Books split into the two lists the home page shows, newest first. */
    async shelves() {
      const all = await load();
      const byNewest = (key) => (a, b) => (b[key] ?? '').localeCompare(a[key] ?? '');
      return {
        reading: all.filter((b) => b.status === 'reading').sort(byNewest('addedAt')),
        finished: all.filter((b) => b.status === 'finished').sort(byNewest('finishedAt')),
      };
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    /** @returns the created book. Title is required; author and notes optional. */
    async add({ title, author = '', notes = '' }, now = new Date()) {
      const trimmed = (title ?? '').trim();
      if (!trimmed) throw new ValidationError('A title is required.');

      const book = {
        id: randomUUID(),
        title: trimmed,
        author: (author ?? '').trim(),
        notes: (notes ?? '').trim(),
        status: 'reading',
        addedAt: now.toISOString(),
        finishedAt: null,
      };
      return write(() => {
        books.push(book);
        return book;
      });
    },

    /** Moves a book between shelves. @returns the updated book, or null if unknown. */
    async setStatus(id, status, now = new Date()) {
      if (status !== 'reading' && status !== 'finished') {
        throw new ValidationError(`Unknown status: ${status}`);
      }
      return write(() => {
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        book.status = status;
        book.finishedAt = status === 'finished' ? now.toISOString() : null;
        return book;
      });
    },

    /** @returns the updated book, or null if unknown. */
    async setNotes(id, notes) {
      return write(() => {
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        book.notes = (notes ?? '').trim();
        return book;
      });
    },
  };
}

export class ValidationError extends Error {}

