/** Escapes text for interpolation into HTML. Every dynamic value goes through this. */
export function esc(value) {
  return String(value ?? '').replace(
    /[&<>"']/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]
  );
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout({ title, body }) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<div class="page">
${body}
</div>
</body>
</html>
`;
}

function bookRow(book) {
  const meta = [book.author, book.status === 'finished' ? `finished ${formatDate(book.finishedAt)}` : null]
    .filter(Boolean)
    .join(' · ');
  return `<li class="row">
  <a class="row-title" href="/books/${esc(book.id)}">${esc(book.title)}</a>
  ${meta ? `<span class="row-meta">${esc(meta)}</span>` : ''}
</li>`;
}

function shelf({ heading, books, empty }) {
  const inner = books.length
    ? `<ul class="rows">${books.map(bookRow).join('\n')}</ul>`
    : `<p class="empty">${esc(empty)}</p>`;
  return `<section>
  <h2>${esc(heading)} <span class="count">${books.length}</span></h2>
  ${inner}
</section>`;
}

export function homePage({ reading, finished, form = {}, error = null }) {
  return layout({
    title: 'Bookshelf',
    body: `<header><h1>Bookshelf</h1></header>

${shelf({ heading: 'Currently reading', books: reading, empty: 'Nothing on the go — add a book below.' })}
${shelf({ heading: 'Finished', books: finished, empty: 'No finished books yet.' })}

<section class="add">
  <h2>Add a book</h2>
  ${error ? `<p class="error" role="alert">${esc(error)}</p>` : ''}
  <form method="post" action="/books">
    <label>Title<input name="title" value="${esc(form.title)}" autocomplete="off" required></label>
    <label>Author<input name="author" value="${esc(form.author)}" autocomplete="off"></label>
    <label>Notes<textarea name="notes" rows="3">${esc(form.notes)}</textarea></label>
    <button type="submit">Add to shelf</button>
  </form>
</section>`,
  });
}

export function bookPage({ book, shareUrl }) {
  const finished = book.status === 'finished';
  const status = finished
    ? `Finished ${formatDate(book.finishedAt)}`
    : `Reading since ${formatDate(book.addedAt)}`;

  const statusForm = finished
    ? `<form method="post" action="/books/${esc(book.id)}/status">
    <input type="hidden" name="status" value="reading">
    <button type="submit" class="link-button">Move back to currently reading</button>
  </form>`
    : `<form method="post" action="/books/${esc(book.id)}/status">
    <input type="hidden" name="status" value="finished">
    <button type="submit">Mark as finished</button>
  </form>`;

  return layout({
    title: book.title,
    body: `<p class="back"><a href="/">&larr; Bookshelf</a></p>

<header class="book-header">
  <h1>${esc(book.title)}</h1>
  ${book.author ? `<p class="author">${esc(book.author)}</p>` : ''}
  <p class="status ${finished ? 'is-finished' : ''}">${esc(status)}</p>
</header>

<section>
  <h2>Notes</h2>
  <form method="post" action="/books/${esc(book.id)}/notes">
    <textarea name="notes" rows="8" placeholder="What did you think?">${esc(book.notes)}</textarea>
    <button type="submit">Save notes</button>
  </form>
</section>

<section class="actions">
  ${statusForm}
</section>

<section class="share">
  <h2>Share this book</h2>
  <input type="text" readonly value="${esc(shareUrl)}" onclick="this.select()" aria-label="Link to this book">
</section>`,
  });
}

export function notFoundPage() {
  return layout({
    title: 'Not found',
    body: `<header><h1>Not found</h1></header>
<p class="empty">That book isn't on the shelf.</p>
<p class="back"><a href="/">&larr; Bookshelf</a></p>`,
  });
}

export function errorPage() {
  return layout({
    title: 'Something went wrong',
    body: `<header><h1>Something went wrong</h1></header>
<p class="empty">The server hit an unexpected error. Check the terminal for details.</p>
<p class="back"><a href="/">&larr; Bookshelf</a></p>`,
  });
}

export const STYLESHEET = `:root {
  --bg: #fbfaf7;
  --panel: #ffffff;
  --ink: #1d1c1a;
  --muted: #6b6862;
  --line: #e5e1d8;
  --accent: #7a5c3e;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
.page { max-width: 44rem; margin: 0 auto; padding: 2.5rem 1.25rem 4rem; }
h1 { font-size: 1.75rem; margin: 0 0 .25rem; letter-spacing: -.01em; }
h2 {
  font-size: .8rem; text-transform: uppercase; letter-spacing: .08em;
  color: var(--muted); margin: 0 0 .75rem; font-weight: 600;
}
section { margin-top: 2.25rem; }
.count {
  display: inline-block; margin-left: .35rem; padding: 0 .4rem;
  border-radius: 999px; background: var(--line); color: var(--muted);
  font-size: .7rem; letter-spacing: 0;
}
.rows { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.row {
  display: flex; flex-wrap: wrap; gap: .25rem .75rem; align-items: baseline;
  justify-content: space-between;
  padding: .8rem .25rem; border-bottom: 1px solid var(--line);
}
.row-title { color: var(--ink); font-weight: 500; text-decoration: none; }
.row-title:hover { color: var(--accent); text-decoration: underline; }
.row-meta { color: var(--muted); font-size: .85rem; }
.empty { color: var(--muted); font-size: .92rem; margin: 0; }
.add, .share { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 1.25rem; }
form { display: flex; flex-direction: column; gap: .85rem; align-items: flex-start; }
