}
.link-button:hover { color: var(--accent); filter: none; }
.error { color: #a4342a; font-size: .9rem; margin: 0 0 .25rem; }
.back { margin: 0 0 1.5rem; font-size: .88rem; }
.back a { color: var(--muted); text-decoration: none; }
.back a:hover { color: var(--accent); }
.book-header { border-bottom: 1px solid var(--line); padding-bottom: 1.25rem; }
