.status { margin: 0; color: var(--muted); font-size: .85rem; }
.status.is-finished { color: #3f7247; }
.share input { font-size: .85rem; color: var(--muted); }
.actions { margin-top: 1.5rem; }
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #171614; --panel: #201f1c; --ink: #ece9e3;
    --muted: #9a958c; --line: #33312c; --accent: #c79a6e;
