import http from 'node:http';

import { createStore, ValidationError } from './store.js';
import { STYLESHEET, bookPage, errorPage, homePage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

function html(res, status, body) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
  });
  res.end(body);
}

function redirect(res, location) {
  // 303 so the browser follows a form POST with a GET.
  res.writeHead(303, { location });
  res.end();
}

/** Reads an `application/x-www-form-urlencoded` body, capped at MAX_BODY_BYTES. */
async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      const err = new Error('Request body too large');
      err.statusCode = 413;
      throw err;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function shareUrl(req, id) {
  // Host is only used to build a copyable link; it is escaped at render time.
  const host = req.headers.host || 'localhost';
  const proto = req.socket.encrypted ? 'https' : 'http';
  return `${proto}://${host}/books/${id}`;
}

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const segments = url.pathname.split('/').filter(Boolean);
    const method = req.method === 'HEAD' ? 'GET' : req.method;

    if (method === 'GET' && segments.length === 0) {
      const { reading, finished } = await store.shelves();
      return html(
        res,
        200,
        homePage({
          reading,
          finished,
          // Repopulated from the query string when an add failed validation.
          form: {
            title: url.searchParams.get('title') ?? '',
            author: url.searchParams.get('author') ?? '',
            notes: url.searchParams.get('notes') ?? '',
          },
          error: url.searchParams.get('error'),
        })
      );
    }

    if (method === 'GET' && url.pathname === '/style.css') {
      res.writeHead(200, { 'content-type': 'text/css; charset=utf-8' });
      return res.end(STYLESHEET);
    }

    if (method === 'POST' && url.pathname === '/books') {
      const form = await readForm(req);
      const fields = {
        title: form.get('title') ?? '',
        author: form.get('author') ?? '',
        notes: form.get('notes') ?? '',
      };
      try {
        const book = await store.add(fields);
        return redirect(res, `/books/${book.id}`);
      } catch (err) {
        if (!(err instanceof ValidationError)) throw err;
        // Bounce back to the form with the values and the reason it failed.
        const params = new URLSearchParams({ ...fields, error: err.message });
        return redirect(res, `/?${params}`);
      }
    }

    if (segments[0] === 'books' && segments.length === 2) {
      const id = segments[1];
      if (method === 'GET') {
        const book = await store.get(id);
        if (!book) return html(res, 404, notFoundPage());
        return html(res, 200, bookPage({ book, shareUrl: shareUrl(req, id) }));
      }
    }

    if (segments[0] === 'books' && segments.length === 3 && method === 'POST') {
      const [, id, action] = segments;

      if (action === 'status') {
        const form = await readForm(req);
        const status = form.get('status') === 'reading' ? 'reading' : 'finished';
        const book = await store.setStatus(id, status);
        if (!book) return html(res, 404, notFoundPage());
        return redirect(res, `/books/${id}`);
      }

      if (action === 'notes') {
        const form = await readForm(req);
        const book = await store.setNotes(id, form.get('notes') ?? '');
        if (!book) return html(res, 404, notFoundPage());
        return redirect(res, `/books/${id}`);
      }
    }

    return html(res, 404, notFoundPage());
  };
}

export function createServer({ dataFile }) {
  const store = createStore(dataFile);
  const app = createApp(store);

  return http.createServer((req, res) => {
    app(req, res).catch((err) => {
      console.error(`${req.method} ${req.url} failed:`, err);
      if (res.headersSent) return res.destroy();
      html(res, err.statusCode ?? 500, errorPage());
    });
  });
}

