import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';

import { ValidationError, createStore } from './store.js';

async function tempFile() {
  const dir = await mkdtemp(path.join(tmpdir(), 'bookshelf-'));
  return path.join(dir, 'books.json');
}

describe('store', () => {
  it('starts empty when the file does not exist yet', async () => {
    const store = createStore(await tempFile());
    expect(await store.all()).toEqual([]);
  });

  it('adds a book to the currently-reading shelf', async () => {
    const store = createStore(await tempFile());
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'spice' });

    expect(book).toMatchObject({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'spice',
      status: 'reading',
      finishedAt: null,
    });
    const { reading, finished } = await store.shelves();
    expect(reading.map((b) => b.title)).toEqual(['Dune']);
    expect(finished).toEqual([]);
  });

  it('trims input and rejects a blank title', async () => {
    const store = createStore(await tempFile());
    const book = await store.add({ title: '  Ulysses  ', author: '  Joyce  ' });
    expect(book.title).toBe('Ulysses');
    expect(book.author).toBe('Joyce');

    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError);
    expect(await store.all()).toHaveLength(1);
  });

  it('defaults author and notes to empty strings', async () => {
    const store = createStore(await tempFile());
    const book = await store.add({ title: 'Untitled' });
    expect(book.author).toBe('');
    expect(book.notes).toBe('');
  });

  it('moves a book to the finished shelf and back', async () => {
    const store = createStore(await tempFile());
    const { id } = await store.add({ title: 'Dune' });

    const finishedBook = await store.setStatus(id, 'finished');
    expect(finishedBook.status).toBe('finished');
    expect(finishedBook.finishedAt).toEqual(expect.any(String));

    let shelves = await store.shelves();
    expect(shelves.reading).toEqual([]);
    expect(shelves.finished.map((b) => b.title)).toEqual(['Dune']);

    const reopened = await store.setStatus(id, 'reading');
    expect(reopened.status).toBe('reading');
    expect(reopened.finishedAt).toBeNull();

    shelves = await store.shelves();
    expect(shelves.reading.map((b) => b.title)).toEqual(['Dune']);
    expect(shelves.finished).toEqual([]);
  });

  it('updates notes', async () => {
    const store = createStore(await tempFile());
    const { id } = await store.add({ title: 'Dune' });

    await store.setNotes(id, '  the sleeper must awaken  ');
    expect((await store.get(id)).notes).toBe('the sleeper must awaken');
  });

  it('returns null for an unknown id instead of throwing', async () => {
    const store = createStore(await tempFile());
    expect(await store.get('nope')).toBeNull();
    expect(await store.setStatus('nope', 'finished')).toBeNull();
    expect(await store.setNotes('nope', 'hi')).toBeNull();
  });

  it('rejects an unknown status', async () => {
    const store = createStore(await tempFile());
    const { id } = await store.add({ title: 'Dune' });
    await expect(store.setStatus(id, 'abandoned')).rejects.toThrow(ValidationError);
  });

  it('persists across store instances', async () => {
    const file = await tempFile();
    const first = createStore(file);
    const { id } = await first.add({ title: 'Dune', author: 'Frank Herbert' });
    await first.setStatus(id, 'finished');

    const second = createStore(file);
    const book = await second.get(id);
    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', status: 'finished' });
  });

  it('creates the data directory if it is missing', async () => {
    const dir = await mkdtemp(path.join(tmpdir(), 'bookshelf-'));
    const file = path.join(dir, 'nested', 'deeper', 'books.json');
    const store = createStore(file);
    await store.add({ title: 'Dune' });

    expect(JSON.parse(await readFile(file, 'utf8'))).toHaveLength(1);
  });

  it('does not lose writes when mutations are issued concurrently', async () => {
    const file = await tempFile();
    const store = createStore(file);

    await Promise.all(
      Array.from({ length: 25 }, (_, i) => store.add({ title: `Book ${i}` }))
    );

    expect(await store.all()).toHaveLength(25);
    expect(JSON.parse(await readFile(file, 'utf8'))).toHaveLength(25);
  });

  it('sorts shelves newest first', async () => {
    const store = createStore(await tempFile());
    await store.add({ title: 'Older' }, new Date('2024-01-01T00:00:00Z'));
    await store.add({ title: 'Newer' }, new Date('2024-06-01T00:00:00Z'));

    const { reading } = await store.shelves();
    expect(reading.map((b) => b.title)).toEqual(['Newer', 'Older']);
  });

  it('refuses to load a corrupt file rather than overwriting it', async () => {
    const file = await tempFile();
    await writeFile(file, '{ this is not json', 'utf8');

    const store = createStore(file);
    await expect(store.all()).rejects.toThrow(/not valid JSON/);
    // The bad file is left untouched so it can be recovered by hand.
    expect(await readFile(file, 'utf8')).toBe('{ this is not json');
  });

  it('treats an empty file as an empty shelf', async () => {
    const file = await tempFile();
    await writeFile(file, '', 'utf8');
    expect(await createStore(file).all()).toEqual([]);
  });
});

afterEach(() => {});

