import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { createServer } from './server.js';

let server;
let base;

beforeEach(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'bookshelf-http-'));
  server = createServer({ dataFile: path.join(dir, 'books.json') });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((resolve) => server.close(resolve));
});

/** Posts a form without following the redirect, like checking the Location header. */
function postForm(pathname, fields) {
  return fetch(`${base}${pathname}`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

async function addBook(fields) {
  const res = await postForm('/books', fields);
  expect(res.status).toBe(303);
  const location = res.headers.get('location');
  expect(location).toMatch(/^\/books\//);
  return location.replace('/books/', '');
}

describe('home page', () => {
  it('shows both shelves as empty to begin with', async () => {
    const body = await (await fetch(base)).text();
    expect(body).toContain('Currently reading');
    expect(body).toContain('Finished');
    expect(body).toContain('add a book below');
  });

  it('lists a new book under currently reading, then under finished', async () => {
    const id = await addBook({ title: 'Dune', author: 'Frank Herbert' });

    let body = await (await fetch(base)).text();
    expect(body).toContain('Dune');
    expect(body).toContain(`/books/${id}`);
    expect(body).toContain('No finished books yet');

    const res = await postForm(`/books/${id}/status`, { status: 'finished' });
    expect(res.status).toBe(303);

    body = await (await fetch(base)).text();
    expect(body).not.toContain('No finished books yet');
    expect(body).toContain('Nothing on the go');
  });

  it('re-shows the form with the values and an error when the title is blank', async () => {
    const res = await postForm('/books', { title: '  ', author: 'Nobody' });
    expect(res.status).toBe(303);

    const body = await (await fetch(base + res.headers.get('location'))).text();
    expect(body).toContain('A title is required.');
    expect(body).toContain('value="Nobody"');
  });

  it('serves the stylesheet', async () => {
    const res = await fetch(`${base}/style.css`);
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toContain('text/css');
    expect(await res.text()).toContain('--accent');
  });
});

describe('book page', () => {
  it('shows the title, author and notes', async () => {
    const id = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Arrakis' });

    const body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).toContain('Dune');
    expect(body).toContain('Frank Herbert');
    expect(body).toContain('Arrakis');
    expect(body).toContain('Mark as finished');
  });

  it('includes a shareable absolute link to itself', async () => {
    const id = await addBook({ title: 'Dune' });
    const body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).toContain(`${base}/books/${id}`);
  });

  it('is reachable directly by URL after a restart, which is what a shared link does', async () => {
    const dir = await mkdtemp(path.join(tmpdir(), 'bookshelf-restart-'));
    const dataFile = path.join(dir, 'books.json');

    const first = createServer({ dataFile });
    await new Promise((r) => first.listen(0, '127.0.0.1', r));
    const firstBase = `http://127.0.0.1:${first.address().port}`;
    const res = await fetch(`${firstBase}/books`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ title: 'Persisted' }),
      redirect: 'manual',
    });
    const id = res.headers.get('location').replace('/books/', '');
    await new Promise((r) => first.close(r));

    const second = createServer({ dataFile });
    await new Promise((r) => second.listen(0, '127.0.0.1', r));
    const secondBase = `http://127.0.0.1:${second.address().port}`;
    const page = await fetch(`${secondBase}/books/${id}`);
    expect(page.status).toBe(200);
    expect(await page.text()).toContain('Persisted');
    await new Promise((r) => second.close(r));
  });

  it('saves notes and shows them on reload', async () => {
    const id = await addBook({ title: 'Dune' });
    await postForm(`/books/${id}/notes`, { notes: 'The sleeper must awaken' });

    const body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).toContain('The sleeper must awaken');
  });

  it('offers a way back to currently reading once finished', async () => {
    const id = await addBook({ title: 'Dune' });
    await postForm(`/books/${id}/status`, { status: 'finished' });

    let body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).toContain('Move back to currently reading');

    await postForm(`/books/${id}/status`, { status: 'reading' });
    body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).toContain('Mark as finished');
  });

  it('escapes user input instead of rendering it as HTML', async () => {
    const id = await addBook({
      title: '<script>alert(1)</script>',
      notes: '</textarea><img src=x>',
    });

    const body = await (await fetch(`${base}/books/${id}`)).text();
    expect(body).not.toContain('<script>alert(1)</script>');
    expect(body).not.toContain('<img src=x>');
    expect(body).toContain('&lt;script&gt;');
  });
});

describe('unknown routes', () => {
  it('404s an unknown book id', async () => {
    const res = await fetch(`${base}/books/does-not-exist`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("isn't on the shelf");
  });

  it('404s an unknown path', async () => {
    expect((await fetch(`${base}/nope`)).status).toBe(404);
  });

  it('404s a status change for an unknown book', async () => {
    const res = await postForm('/books/does-not-exist/status', { status: 'finished' });
    expect(res.status).toBe(404);
  });

  it('rejects an oversized request body', async () => {
    const res = await postForm('/books', { title: 'x'.repeat(70 * 1024) });
    expect(res.status).toBe(413);
  });
});

